{"title":"Bioluminescent Abyss","code":"let jellies = [];
let plankton = [];

function setup() {
  createCanvas(windowWidth, windowHeight);
  colorMode(HSB, 360, 100, 100, 1);

  for (let i = 0; i < 6; i++) {
    jellies.push(new Jellyfish());
  }
  for (let i = 0; i < 150; i++) {
    plankton.push(new Plankton());
  }
}

function draw() {
  background(230, 80, 8, 0.3);

  let wind = noise(frameCount * 0.005) - 0.5;

  for (let p of plankton) {
    p.update(wind);
    p.display();
  }

  let count = floor(params.jellyCount);
  while (jellies.length < count) {
    jellies.push(new Jellyfish());
  }
  while (jellies.length > count) {
    jellies.pop();
  }

  for (let j of jellies) {
    j.update(wind);
    j.display();
  }
}

class Plankton {
  constructor() {
    this.reset();
  }

  reset() {
    this.x = random(width);
    this.y = random(height);
    this.size = random(1, 3);
    this.alpha = random(0.1, 0.6);
    this.speedY = random(0.2, 0.8);
  }

  update(wind) {
    this.y -= this.speedY * params.speed;
    this.x += wind * params.speed;
    if (this.y < 0) {
      this.y = height;
      this.x = random(width);
    }
    if (this.x < 0) this.x = width;
    if (this.x > width) this.x = 0;
  }

  display() {
    noStroke();
    let h = params.glowColor === 'Cyan' ? 180 : (params.glowColor === 'Teal' ? 160 : 280);
    fill(h, 40, 90, this.alpha);
    ellipse(this.x, this.y, this.size);
  }
}

class Jellyfish {
  constructor() {
    this.x = random(width);
    this.y = random(height + 100, height * 2);
    this.size = random(40, 90);
    this.speedY = random(0.5, 1.5);
    this.pulseSpeed = random(0.03, 0.07);
    this.pulseOffset = random(100);
    this.tentacles = [];

    let tentacleCount = floor(random(6, 12));
    for (let i = 0; i < tentacleCount; i++) {
      this.tentacles.push(new Tentacle(this, i, tentacleCount));
    }
  }

  update(wind) {
    let s = params.speed;
    this.y -= this.speedY * s;
    this.x += (sin(frameCount * 0.01 + this.pulseOffset) * 0.5 + wind * 2) * s;

    if (this.y < -this.size * 3) {
      this.y = height + random(50, 200);
      this.x = random(width);
    }

    for (let t of this.tentacles) {
      t.update(s);
    }
  }

  display() {
    push();
    translate(this.x, this.y);

    let pulse = sin(frameCount * this.pulseSpeed * params.speed + this.pulseOffset);
    let currentW = this.size * (1 + pulse * 0.15);
    let currentH = this.size * 0.8 * (1 - pulse * 0.1);

    for (let t of this.tentacles) {
      t.display();
    } 

    noFill();
    let h = params.glowColor === 'Cyan' ? 180 : (params.glowColor === 'Teal' ? 160 : 280);

    for (let i = 4; i > 0; i--) {
      stroke(h, 70, 90, 0.05 * i);
      strokeWeight(i * 2);
      arc(0, 0, currentW + i * 2, currentH + i * 2, PI, TWO_PI);
    }

    fill(h, 60, 40, 0.6);
    noStroke();
    arc(0, 0, currentW, currentH, PI, TWO_PI);

    fill(h, 20, 100, 0.8);
    arc(0, 0, currentW * 0.8, currentH * 0.8, PI, TWO_PI);

    fill(h, 80, 100, 0.3);
    arc(0, 0, currentW * 0.9, currentH * 0.9, PI, TWO_PI, OPEN);

    pop();
  }
}

class Tentacle {
  constructor(jelly, index, total) {
    this.jelly = jelly;
    this.index = index;
    this.total = total;
    this.length = random(120, 250);
    this.segments = 12;
    this.offset = random(100);
  }

  update(s) {
    // Handled mostly by kinematics in display or basic wobble
  }

  display() {
    let h = params.glowColor === 'Cyan' ? 180 : (params.glowColor === 'Teal' ? 160 : 280);
    noFill();

    let startX = map(this.index, 0, this.total - 1, -this.jelly.size * 0.6, this.jelly.size * 0.6);
    if (this.total === 1) startX = 0;

    beginShape();
    for (let i = 0; i <= this.segments; i++) {
      let progress = i / this.segments;
      let px = startX + sin(frameCount * 0.05 + this.offset + i * 0.5) * progress * 15;
      let py = progress * this.length;

      let alpha = map(progress, 0, 1, 0.5, 0);
      stroke(h, 70, 90, alpha);
      strokeWeight(map(progress, 0, 1, 2, 0.5));
      vertex(px, py);
    }
    endShape();
  }
}","params":[{"id":"speed","name":"Drift Speed","type":"number","default":1,"min":0.2,"max":3,"step":0.1},{"id":"jellyCount","name":"Jellyfish Count","type":"number","default":4,"min":1,"max":10,"step":1},{"id":"glowColor","name":"Bioluminescence","type":"enum","default":"Cyan","options":["Cyan","Teal","Purple"]}]}

{
  "title": "Stellar Murmuration",
  "code": "let birds = [];
let numBirds = 350;

function setup() {
  createCanvas(windowWidth, windowHeight);
  colorMode(HSB, 360, 100, 100, 1);
  for (let i = 0; i < numBirds; i++) {
    birds.push(new Bird());
  }
}

function draw() {
  background(220, 40, 10, 0.25);

  let cx = width / 2;
  let cy = height / 2;

  // Draw invisible lighthouse beam / glow
  noFill();
  for (let r = 150; r > 0; r -= 30) {
    let alpha = map(r, 0, 150, 0.15, 0);
    stroke(60, 80, 90, alpha);
    strokeWeight(r);
    ellipse(cx, cy, r);
  }

  // Rotating light beam from lighthouse
  let beamAngle = frameCount * 0.02 * params.speed;
  push();
  translate(cx, cy);
  rotate(beamAngle);
  noStroke();
  fill(60, 90, 100, 0.08);
  triangle(0, 0, -width, -height * 1.5, width, -height * 1.5);
  pop();

  // Update and show birds
  for (let i = 0; i < birds.length; i++) {
    birds[i].update();
    birds[i].show();
  }
}

class Bird {
  constructor() {
    this.pos = createVector(random(width), random(height));
    this.vel = p5.Vector.random2D().mult(random(2, 4));
    this.acc = createVector(0, 0);
    this.maxSpeed = 5;
    this.maxForce = 0.2;
    this.hue = random(180, 260);
  }

  update() {
    let cx = width / 2;
    let cy = height / 2;
    let center = createVector(cx, cy);

    // Spiral force around the lighthouse
    let toCenter = p5.Vector.sub(center, this.pos);
    let distToCenter = toCenter.mag();

    // Tangent vector for spiral rotation
    let tangent = createVector(-toCenter.y, toCenter.x);
    tangent.normalize();

    let desiredDist = 200;
    let radialForce = toCenter.copy();
    radialForce.normalize();
    if (distToCenter < desiredDist) {
      radialForce.mult(-1);
    }

    let spiralDir = tangent.mult(2.5).add(radialForce.mult(0.5));
    spiralDir.normalize();
    spiralDir.mult(this.maxSpeed);

    let steer = p5.Vector.sub(spiralDir, this.vel);
    steer.limit(this.maxForce);
    this.acc.add(steer.mult(params.swarmTightness));

    // Mouse interaction / wind
    let mouse = createVector(mouseX, mouseY);
    let dMouse = p5.Vector.dist(this.pos, mouse);
    if (dMouse < 150) {
      let away = p5.Vector.sub(this.pos, mouse);
      away.normalize();
      away.mult(map(dMouse, 0, 150, 5, 0));
      this.acc.add(away);
    }

    // Update physics
    let spdMult = params.speed;
    this.vel.add(p5.Vector.mult(this.acc, spdMult));
    this.vel.limit(this.maxSpeed * spdMult);
    this.pos.add(this.vel);
    this.acc.mult(0);

    // Screen wrap
    if (this.pos.x < 0) this.pos.x = width;
    if (this.pos.x > width) this.pos.x = 0;
    if (this.pos.y < 0) this.pos.y = height;
    if (this.pos.y > height) this.pos.y = 0;
  }

  show() {
    let angle = this.vel.heading();
    push();
    translate(this.pos.x, this.pos.y);
    rotate(angle);
    noStroke();

    // Color variation based on params and speed
    let h = (this.hue + frameCount * 0.1) % 360;
    fill(h, 70, 90, 0.8);

    // Bird shape (triangle)
    beginShape();
    vertex(6, 0);
    vertex(-6, -3);
    vertex(-3, 0);
    vertex(-6, 3);
    endShape(CLOSE);
    pop();
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
