{
  "title": "Moonlit Meadow Fireflies",
  "code": "let fireflies = [];
let blades = [];

function setup() {
  createCanvas(windowWidth, windowHeight);
  colorMode(HSB, 360, 100, 100, 1);

  // Initialize maximum possible fireflies
  for (let i = 0; i < 150; i++) {
    fireflies.push(new Firefly());
  }

  // Initialize meadow grass blades
  let bladeCount = width < 768 ? 80 : 180;
  for (let i = 0; i < bladeCount; i++) {
    blades.push(new GrassBlade(random(width), height));
  }
}

function draw() {
  // Moonlit night sky gradient
  let c1 = color(220, 80, 10);
  let c2 = color(240, 60, 25);
  setGradient(0, 0, width, height, c1, c2);

  // Draw Moon
  noStroke();
  fill(60, 20, 95, 0.15);
  ellipse(width * 0.8, height * 0.2, 220, 220);
  fill(60, 30, 100, 0.8);
  ellipse(width * 0.8, height * 0.2, 140, 140);

  // Update and draw grass background layers
  for (let b of blades) {
    b.update();
    b.display(0.4);
  }

  // Update and draw fireflies
  let activeCount = int(params.fireflyCount);
  for (let i = 0; i < activeCount; i++) {
    let f = fireflies[i];
    f.update();
    f.display();
  }

  // Draw foreground grass silhouettes
  for (let b of blades) {
    b.display(1.0);
  }
}

function setGradient(x, y, w, h, c1, c2) {
  noFill();
  for (let i = y; i <= y + h; i++) {
    let inter = map(i, y, y + h, 0, 1);
    let c = lerpColor(c1, c2, inter);
    stroke(c);
    line(x, i, x + w, i);
  }
}

class Firefly {
  constructor() {
    this.reset();
  }

  reset() {
    this.pos = createVector(random(width), random(height * 0.2, height * 0.9));
    this.vel = createVector(0, 0);
    this.acc = createVector(0, 0);
    this.maxSpeed = random(0.5, 1.5);
    this.history = [];
    this.maxHistory = floor(random(15, 35));
    this.phase = random(TWO_PI);
    this.blinkSpeed = random(0.02, 0.08);
    this.hue = params.colorScheme === 'Golden' ? random(35, 60) : (params.colorScheme === 'Emerald' ? random(90, 150) : random(180, 220));
  }

  update() {
    let time = millis() * 0.001 * params.speed;

    // Perlin noise movement
    let n = noise(this.pos.x * 0.003, this.pos.y * 0.003, time * 0.5);
    let angle = n * TWO_PI * 4;

    let noiseDir = p5.Vector.fromAngle(angle);
    noiseDir.mult(0.2);
    this.acc.add(noiseDir);

    // Gentle pull towards mouse if close
    let mouse = createVector(mouseX, mouseY);
    let d = dist(this.pos.x, this.pos.y, mouse.x, mouse.y);
    if (d < 200 && mouseX > 0 && mouseY > 0) {
      let pull = p5.Vector.sub(mouse, this.pos);
      pull.setMag(map(d, 0, 200, 0.5, 0));
      if (params.glowIntensity > 1) {
        this.acc.add(pull);
      } else {
        this.acc.sub(pull);
      }
    }

    this.vel.add(this.acc);
    this.vel.limit(this.maxSpeed * params.speed);
    this.pos.add(this.vel);
    this.acc.mult(0);

    // Screen wrap
    if (this.pos.x < 0) this.pos.x = width;
    if (this.pos.x > width) this.pos.x = 0;
    if (this.pos.y < 0) this.pos.y = height;
    if (this.pos.y > height) this.pos.y = 0;

    // Trail history
    if (frameCount % 2 === 0) {
      this.history.push(this.pos.copy());
      if (this.history.length > this.maxHistory) {
        this.history.shift();
      }
    }

    this.phase += this.blinkSpeed * params.speed;
  }

  display() {
    let glow = (sin(this.phase) + 1) * 0.5;
    glow = pow(glow, 2) * params.glowIntensity;

    // Draw luminous trails
    for (let i = 0; i < this.history.length; i++) {
      let pt = this.history[i];
      let alpha = map(i, 0, this.history.length, 0, 0.4) * glow;
      stroke(this.hue, 80, 100, alpha);
      strokeWeight(map(i, 0, this.history.length, 0.5, 3));
      point(pt.x, pt.y);
    }

    // Draw firefly body
    noStroke();
    fill(this.hue, 30, 100, glow);
    ellipse(this.pos.x, this.pos.y, 6 * glow, 6 * glow);
    fill(this.hue, 10, 100, glow * 1.5);
    ellipse(this.pos.x, this.pos.y, 2, 2);
  }
}

class GrassBlade {
  constructor(x, y) {
    this.x = x;
    this.baseY = y;
    this.h = random(40, 140);
    this.angle = random(-0.2, 0.2);
    this.swaySpeed = random(0.01, 0.03);
    this.swayAmount = random(0.05, 0.15);
  }

  update() {
    // Static silhouette, no major update needed per frame except subtle wind
  }

  display(layerAlpha) {
    let time = millis() * 0.002;
    let sway = sin(time + this.x) * this.swayAmount;
    let tipX = this.x + sin(this.angle + sway) * this.h;
    let tipY = this.baseY - cos(this.angle + sway) * this.h;

    stroke(230, 40, layerAlpha > 0.5 ? 12 : 25, layerAlpha);
    strokeWeight(layerAlpha > 0.5 ? 3 : 6);
    noFill();

    beginShape();
    vertex(this.x, this.baseY);
    quadraticVertex(this.x + (tipX - this.x) * 0.5, this.baseY - this.h * 0.5, tipX, tipY);
    endShape();
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
