{"title":"Jewel Coral Symphony","code":"let boids = [];
let coralPoints = [];
let numBoids = 150;

function setup() {
  createCanvas(windowWidth, windowHeight);
  colorMode(HSB, 360, 100, 100, 1);

  // Initialize boids
  for (let i = 0; i < 400; i++) {
    boids.push(new Boid(random(width), random(height)));
  }

  generateCoral();
}

function draw() {
  let bgHue = params.bgPalette === 'Deep Ocean' ? 220 : (params.bgPalette === 'Midnight' ? 260 : 30);
  let bgSat = params.bgPalette === 'Sunset' ? 40 : 80;
  background(bgHue, bgSat, 10);

  // Draw subtle background rays / glow
  noStroke();
  for (let i = 0; i < 3; i++) {
    fill(bgHue, 30, 20, 0.05);
    ellipse(width * 0.5, height * 1.2, width * (1.5 - i * 0.3), height * 1.5);
  }

  // Update and draw coral silhouette
  drawCoral();

  // Update and draw boids
  let maxBoids = floor(map(params.fishDensity, 0.1, 2, 50, 350));
  for (let i = 0; i < maxBoids; i++) {
    let b = boids[i];
    b.update();
    b.show();
  }
}

function generateCoral() {
  coralPoints = [];
  let rootX = width * 0.5;
  let rootY = height;

  // Generate recursive coral branches
  branch(rootX, rootY, -HALF_PI, 120, 6);
}

function branch(x, y, angle, len, depth) {
  if (depth <= 0) return;

  let endX = x + cos(angle) * len;
  let endY = y + sin(angle) * len;

  coralPoints.push({x1: x, y1: y, x2: endX, y2: endY, depth: depth});

  let nBranches = floor(random(2, 4));
  for (let i = 0; i < nBranches; i++) {
    let newAngle = angle + random(-0.6, 0.6);
    let newLen = len * random(0.65, 0.85);
    branch(endX, endY, newAngle, newLen, depth - 1);
  }
}

function drawCoral() {
  stroke(20, 20, 8);
  noFill();

  // Base coral silhouette shadow/glow
  for (let c of coralPoints) {
    strokeWeight(c.depth * 3.5 * (width / 1200));
    strokeCap(ROUND);
    line(c.x1, c.y1, c.x2, c.y2);
  }

  // Inner coral core
  stroke(15, 40, 15);
  for (let c of coralPoints) {
    strokeWeight(c.depth * 2 * (width / 1200));
    line(c.x1, c.y1, c.x2, c.y2);
  }
}

class Boid {
  constructor(x, y) {
    this.position = createVector(x, y);
    this.velocity = p5.Vector.random2D();
    this.velocity.setMag(random(2, 4));
    this.acceleration = createVector();
    this.maxSpeed = random(2.5, 4.5);
    this.maxForce = 0.2;
    this.hueOffset = random(360);
    this.size = random(6, 12);
  }

  update() {
    let s = params.speed;
    this.velocity.add(this.acceleration);
    this.velocity.limit(this.maxSpeed * s);
    this.position.add(this.velocity);
    this.acceleration.mult(0);

    // Wrap edges
    if (this.position.x < -50) this.position.x = width + 50;
    if (this.position.x > width + 50) this.position.x = -50;
    if (this.position.y < -50) this.position.y = height + 50;
    if (this.position.y > height + 50) this.position.y = -50;

    // Apply behaviors
    let flow = this.flowFieldForce();
    let avoid = this.avoidCoral();
    let mouse = this.interactMouse();

    this.applyForce(flow.mult(1.2));
    this.applyForce(avoid.mult(2.5));
    this.applyForce(mouse.mult(1.5));
  }

  applyForce(force) {
    this.acceleration.add(force);
  }

  flowFieldForce() {
    let freq = 0.002 * params.flowDetail;
    let angle = noise(this.position.x * freq, this.position.y * freq, frameCount * 0.005 * params.speed) * TWO_PI * 2;
    let force = p5.Vector.fromAngle(angle);
    force.setMag(this.maxSpeed);
    let steer = p5.Vector.sub(force, this.velocity);
    steer.limit(this.maxForce);
    return steer;
  }

  avoidCoral() {
    let steer = createVector(0, 0);
    let count = 0;
    for (let c of coralPoints) {
      let a = createVector(c.x1, c.y1);
      let b = createVector(c.x2, c.y2);
      let p = this.position;

      // Distance to line segment
      let ab = p5.Vector.sub(b, a);
      let ap = p5.Vector.sub(p, a);
      let t = ap.dot(ab) / ab.magSq();
      t = constrain(t, 0, 1);
      let closest = p5.Vector.add(a, ab.mult(t));

      let d = p5.Vector.dist(p, closest);
      let threshold = c.depth * 15 + 20;
      if (d < threshold) {
        let diff = p5.Vector.sub(p, closest);
        diff.normalize();
        diff.div(d + 1); // Closer is stronger
        steer.add(diff);
        count++;
      }
    }
    if (count > 0) {
      steer.div(count);
      steer.setMag(this.maxSpeed);
      steer.sub(this.velocity);
      steer.limit(this.maxForce * 2);
    }
    return steer;
  }

  interactMouse() {
    let mouse = createVector(mouseX, mouseY);
    let d = p5.Vector.dist(this.position, mouse);
    let steer = createVector(0, 0);
    if (d < 150 && mouseX > 0 && mouseY > 0) {
      let repulse = p5.Vector.sub(this.position, mouse);
      repulse.normalize();
      repulse.mult(this.maxSpeed);
      steer = p5.Vector.sub(repulse, this.velocity);
      steer.limit(this.maxForce * 2);
    }
    return steer;
  }

  show() {
    push();
    translate(this.position.x, this.position.y);
    rotate(this.velocity.heading());

    // Jewel color calculation
    let h;
    if (params.fishPalette === 'Ruby & Sapphire') {
      h = (sin(frameCount * 0.02 + this.hueOffset) > 0) ? 350 : 210;
    } else if (params.fishPalette === 'Emerald Gold') {
      h = (sin(frameCount * 0.02 + this.hueOffset) > 0) ? 140 : 45;
    } else {
      // Prism Rainbow
      h = (frameCount * 0.5 + this.hueOffset * 2) % 360;
    }

    let s = 90;
    let b = 95;

    // Fish body (sleek jewel shape)
    noStroke();
    fill(h, s, b, 0.9);
    beginShape();
    vertex(this.size, 0);
    vertex(-this.size * 0.8, this.size * 0.5);
    vertex(-this.size * 0.5, 0);
    vertex(-this.size * 0.8, -this.size * 0.5);
    endShape(CLOSE);

    // Glowing tail fin
    fill(h, s - 20, b, 0.7);
    beginShape();
    vertex(-this.size * 0.5, 0);
    vertex(-this.size * 1.3, this.size * 0.7);
    vertex(-this.size * 1.0, 0);
    vertex(-this.size * 1.3, -this.size * 0.7);
    endShape(CLOSE);

    pop();
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  generateCoral();
