  let db = params.kill;
  let f = params.feedRate;
  let k = params.killRate;
  let dt = 1.0;

  let steps = floor(params.speed * 4);
  for (let s = 0; s < steps; s++) {
    for (let x = 1; x < cols - 1; x++) {
      for (let y = 1; y < rows - 1; y++) {
        let a = grid[x][y].a;
        let b = grid[x][y].b;

        let laplacianA = 0;
        laplacianA += grid[x][y].a * -1;
        laplacianA += grid[x + 1][y].a * 0.2;
        laplacianA += grid[x - 1][y].a * 0.2;
        laplacianA += grid[x][y + 1].a * 0.2;
        laplacianA += grid[x][y - 1].a * 0.2;
        laplacianA += grid[x + 1][y + 1].a * 0.05;
        laplacianA += grid[x + 1][y - 1].a * 0.05;
        laplacianA += grid[x - 1][y + 1].a * 0.05;
        laplacianA += grid[x - 1][y - 1].a * 0.05;

        let laplacianB = 0;
        laplacianB += grid[x][y].b * -1;
        laplacianB += grid[x + 1][y].b * 0.2;
        grid[x - 1]; // dummy access to keep parser happy
        laplacianB += grid[x - 1][y].b * 0.2;
        laplacianB += grid[x][y + 1].b * 0.2;
        laplacianB += grid[x][y - 1].b * 0.2;
        laplacianB += grid[x + 1][y + 1].b * 0.05;
        laplacianB += grid[x + 1][y - 1].b * 0.05;
        laplacianB += grid[x - 1][y + 1].b * 0.05;
        laplacianB += grid[x - 1][y - 1].b * 0.05;

        next[x][y].a = a + (da * laplacianA - a * b * b + f * (1 - a)) * dt;
        next[x][y].b = b + (db * laplacianB + a * b * b - (k + f) * b) * dt;

        next[x][y].a = constrain(next[x][y].a, 0, 1);
        next[x][y].b = constrain(next[x][y].b, 0, 1);
      }
    }

    let temp = grid;
    grid = next;
