  "title": "Milk and Ink Plume",
  "code": "let particles = [];
const maxParticles = 600;

function setup() {
  createCanvas(windowWidth, windowHeight);
  colorMode(HSB, 360, 100, 100, 100);
  for (let i = 0; i < maxParticles; i++) {
    particles.push(new Particle());
  }
}

function draw() {
  background(params.bgColor);

  let numActive = floor(map(params.density, 0.1, 2, 100, maxParticles));

  for (let i = 0; i < numActive; i++) {
    let p = particles[i];
    p.update();
    p.display();
  }
}

class Particle {
  constructor() {
    this.reset();
  }

  reset() {
    this.x = random(width * 0.3, width * 0.7);
    this.y = height + random(20, 100);
    this.vx = 0;
    this.vy = random(-3, -1);
    this.alpha = random(40, 90);
    this.size = random(4, 25);
    this.life = random(200, 500);
    this.maxLife = this.life;
    this.colorOffset = random(360);
  }

  update() {
    let nscale = 0.002 * params.complexity;
    let angle = noise(this.x * nscale, this.y * nscale, frameCount * 0.003 * params.speed) * TWO_PI * 2;

    let flowForceX = cos(angle) * 0.8;
    let flowForceY = sin(angle) * 0.8 - 0.4;

    this.vx += flowForceX * 0.1;
    this.vy += flowForceY * 0.1;

    this.vx *= 0.95;
    this.vy *= 0.95;

    this.x += this.vx * params.speed;
    this.y += this.vy * params.speed;

    this.life--;
    this.size += 0.05 * params.spread;

    if (this.life <= 0 || this.y < -50 || this.x < -50 || this.x > width + 50) {
      this.reset();
    }
  }

  display() {
    let fade = map(this.life, 0, this.maxLife, 0, 1);
    let c;
    if (params.inkColor === "Indigo") {
      c = color(230 + sin(frameCount * 0.01 + this.colorOffset) * 20, 80, 20, this.alpha * fade);
    } else if (params.inkColor === "Crimson") {
      c = color(340 + sin(frameCount * 0.01 + this.colorOffset) * 20, 85, 40, this.alpha * fade);
    } else {
      c = color((this.colorOffset + frameCount * 0.2) % 360, 70, 50, this.alpha * fade);
    }

    noStroke();
    fill(c);
    ellipse(this.x, this.y, this.size);
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
