let cols, rows;
let resolution = 8;
let dA = 1.0;
let dB = 0.5;
let feed = 0.055;
let k = 0.062;

function setup() {
  createCanvas(windowWidth, windowHeight);
  cols = floor(width / resolution);
  rows = floor(height / resolution);

  grid = [];
  nextGrid = [];
  for (let x = 0; x < cols; x++) {
    grid[x] = [];
    nextGrid[x] = [];
    for (let y = 0; y < rows; y++) {
      grid[x][y] = { a: 1.0, b: 0.0 };
      nextGrid[x][y] = { a: 1.0, b: 0.0 };
    }
  }

  // Seed initial spots
  let cx = floor(cols / 2);
  let cy = floor(rows / 2);
  for (let i = -5; i <= 5; i++) {
    for (let j = -5; j <= 5; j++) {
      if (cx + i >= 0 && cx + i < cols && cy + j >= 0 && cy + j < rows) {
        grid[cx + i][cy + j].b = 1.0;
      }
    }
  }
  // Random extra seeds
  for (let n = 0; n < 5; n++) {
    let rx = floor(random(10, cols - 10));
    let ry = floor(random(10, rows - 10));
    for (let i = -3; i <= 3; i++) {
      for (let j = -3; j <= 3; j++) {
        grid[rx + i][ry + j].b = 1.0;
      }
    }
  }
}

function draw() {
  background(0);

  // Adjust parameters smoothly or from controls
  let spd = floor(params.speed * 3) + 1;
  let cType = params.colorPalette;
  feed = params.feedRate;
  k = params.killRate;

  for (let step = 0; step < spd; step++) {
    for (let x = 1; x < cols - 1; x++) {
      for (let y = 1; y < rows - 1; y++) {
        let a = grid[x][y].a;
        let b = grid[x][y].b;

        let lapA = laplacianA(x, y);
        let lapB = laplacianB(x, y);

        let ab2 = a * b * b;

        let nextA = a + (dA * lapA - ab2 + feed * (1 - a)) * 1.0;
        let nextB = b + (dB * lapB + ab2 - (k + feed) * b) * 1.0;

        nextGrid[x][y].a = constrain(nextA, 0, 1);
        nextGrid[x][y].b = constrain(nextB, 0, 1);
      }
    }

    // Swap grids
    let temp = grid;
    grid = nextGrid;
    nextGrid = temp;
  }

  noStroke();
  for (let x = 0; x < cols; x++) {
    for (let y = 0; y < rows; y++) {
      let a = grid[x][y].a;
      let b = grid[x][y].b;
      let val = a - b;

      if (cType === "Neon Matrix") {
        let r = floor(val * 20);
        let g = floor(b * 255);
        let bCol = floor(a * 100);
        fill(r, g, bCol);
      } else if (cType === "Deep Ocean") {
        let r = floor(b * 50);
        let g = floor(val * 150);
        let bCol = floor(a * 255);
        fill(r, g, bCol);
      } else if (cType === "Magma") {
        let r = floor(b * 255);
        let g = floor(val * 120);
        let bCol = floor(a * 30);
        fill(r, g, bCol);
      } else {
        let colVal = floor((1 - b) * 255);
        fill(colVal);
      }

      rect(x * resolution, y * resolution, resolution, resolution);
    }
  }
}

function laplacianA(x, y) {
  let sumA = 0;
  sumA += grid[x][y].a * -1;
  sumA += grid[x - 1][y].a * 0.2;
  sumA += grid[x + 1][y].a * 0.2;
  sumA += grid[x][y - 1].a * 0.2;
  sumA += grid[x][y + 1].a * 0.2;
  sumA += grid[x - 1][y - 1].a * 0.05;
  sumA += grid[x + 1][y - 1].a * 0.05;
  sumA += grid[x - 1][y + 1].a * 0.05;
  sumA += grid[x + 1][y + 1].a * 0.05;
  return sumA;
}

function laplacianB(x, y) {
  let sumB = 0;
  sumB += grid[x][y].b * -1;
  sumB += grid[x - 1][y].b * 0.2;
  sumB += grid[x + 1][y].b * 0.2;
  sumB += grid[x][y - 1].b * 0.2;
  sumB += grid[x][y + 1].b * 0.2;
  sumB += grid[x - 1][y - 1].b * 0.05;
  sumB += grid[x + 1][y - 1].b * 0.05;
  sumB += grid[x - 1][y + 1].b * 0.05;
  sumB += grid[x + 1][y + 1].b * 0.05;
  return sumB;
}

function mousePressed() {
  let mx = floor(mouseX / resolution);
  let my = floor(mouseY / resolution);
  for (let i = -4; i <= 4; i++) {
    for (let j = -4; j <= 4; j++) {
