  "title": "Low-Poly Mountain Flight",
  "code": "let terrainCols = 40;
let terrainRows = 60;
let terrainScale = 40;
let zOffset = 0;

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
  noStroke();
}

function draw() {
  background(params.nightMode ? 15 : 220, params.nightMode ? 15 : 230, params.nightMode ? 35 : 255);

  let spd = params.speed * 0.5;
  zOffset += spd;

  if (params.nightMode) {
    ambientLight(40, 40, 80);
    directionalLight(200, 150, 255, 0, 1, -0.5);
  } else {
    ambientLight(150, 150, 150);
    directionalLight(255, 240, 220, 0, 1, -0.5);
  }

  push();
  translate(0, 200, -600);
  rotateX(QUARTER_PI * 0.8);
  rotateZ(frameCount * 0.001 * params.turnSpeed);

  let heights = [];
  let mScale = params.mountainScale * 0.01;

  for (let y = 0; y < terrainRows; y++) {
    heights[y] = [];
    for (let x = 0; x < terrainCols; x++) {
      let nx = x * 0.15;
      let ny = (y + zOffset) * 0.15;
      let h = noise(nx, ny) * 350 * mScale;

      let distFromCenter = abs(x - terrainCols / 2) / (terrainCols / 2);
      h -= pow(distFromCenter, 2) * 200 * mScale;
      heights[y][x] = h;
    }
  }

  for (let y = 0; y < terrainRows - 1; y++) {
    beginShape(TRIANGLE_STRIP);
    for (let x = 0; x < terrainCols; x++) {
      let h1 = heights[y][x];
      let h2 = heights[y + 1][x];

      let col1 = getTerrainColor(h1);
      let col2 = getTerrainColor(h2);

      fill(col1);
      vertex((x - terrainCols / 2) * terrainScale, (y - terrainRows / 2) * terrainScale, h1);
      fill(col2);
      vertex((x - terrainCols / 2) * terrainScale, (y + 1 - terrainRows / 2) * terrainScale, h2);
    }
    endShape();
  }

  pop();
}

function getTerrainColor(h) {
  let peak = params.nightMode ? color(240, 245, 255) : color(255);
  let rock = params.nightMode ? color(60, 70, 90) : color(120, 110, 100);
  let base = params.nightMode ? color(20, 40, 30) : color(40, 130, 60);

  if (h > 150) {
    return peak;
  } else if (h > 50) {
    let amt = map(h, 50, 150, 0, 1);
    return lerpColor(rock, peak, amt);
  } else if (h > -50) {
    let amt = map(h, -50, 50, 0, 1);
    return lerpColor(base, rock, amt);
  } else {
    return base;
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
