  background(params.bgHue, 40, 15);

  // Moving colored lights
  let t = millis() * 0.001 * params.speed;
  let light1X = cos(t) * 300;
  let light1Y = sin(t * 0.7) * 300;
  let light1Z = sin(t) * 300 + 200;
  pointLight( (t * 50) % 360, 80, 100, light1X, light1Y, light1Z);

  let light2X = sin(t * 1.3) * 300;
  let light2Y = cos(t * 0.9) * 300;
  let light2Z = cos(t * 1.1) * 300 - 200;
  pointLight( (t * 50 + 180) % 360, 80, 100, light2X, light2Y, light2Z);

  ambientLight(20);

  push();
  rotateX(angleX);
  rotateY(angleY);

  // Draw crystalline structure
  let detail = floor(params.complexity);
  for (let i = 0; i < crystals.length; i++) {
    let v1 = crystals[i];
    for (let j = i + 1; j < crystals.length; j++) {
      let v2 = crystals[j];
      let d = p5.Vector.dist(v1, v2);
      if (d < 180) {
        // Draw connecting struts
        stroke((i * 30 + frameCount * 0.5 * params.speed) % 360, 70, 90, 80);
        strokeWeight(params.wireframe ? 2 : 1);
        noFill();
        line(v1.x, v1.y, v1.z, v2.x, v2.y, v2.z);
      }
    }
  }

  // Draw faceted crystal nodes
  noStroke();
  for (let i = 0; i < crystals.length; i++) {
    let v = crystals[i];
    push();
    translate(v.x, v.y, v.z);
    specularMaterial((i * 35) % 360, 60, 90);
    shininess(50);

    if (params.shapeType === 'Box') {
      box(25);
    } else if (params.shapeType === 'Sphere') {
      sphere(18, detail, detail);
    } else {
      torus(20, 8, detail, detail);
    }
    pop();
  }

  // Central core crystal
  push();
  rotateZ(t * 0.5);
  specularMaterial((frameCount * 0.2) % 360, 40, 100);
  shininess(100);
  if (params.shapeType === 'Box') {
    box(70);
  } else if (params.shapeType === 'Sphere') {
    sphere(50, detail, detail);
  } else {
    torus(50, 15, detail, detail);
  }
  pop();

  pop();

  // Update rotation angles
  angleX += 0.005 * params.speed;
  angleY += 0.008 * params.speed;
}

