{"title":"Recursive Wind-Swept Fern","code":"let fronds = [];

function setup() {
  createCanvas(windowWidth, windowHeight);
  angleMode(DEGREES);
}

function draw() {
  background(params.bgColor);

  let time = millis() * 0.001 * params.speed;
  let wind = sin(time * 50) * params.windStrength;

  translate(width / 2, height - 50);

  let iterations = int(params.depth);
  let baseLen = min(width, height) * 0.22;

  stroke(params.fernColor);
  noFill();
  strokeWeight(2);

  // Draw main stem
  push();
  let sway = sin(time * 40) * params.windStrength * 0.2;
  rotate(sway);
  line(0, 0, 0, -baseLen);
  translate(0, -baseLen);
  drawFernLeaf(baseLen, iterations, time, wind, 0);
  pop();

  // Draw side fronds for a lush bush look
  for (let i = 1; i <= 3; i++) {
    push();
    let sideAngle = i * 25 - 40;
    rotate(sideAngle);
    let subLen = baseLen * 0.7;
    let localSway = sway + sin(time * 30 + i) * params.windStrength;
    stroke(red(color(params.fernColor)) * 0.9, green(color(params.fernColor)) * 0.9, blue(color(params.fernColor)) * 0.9);
    strokeWeight(max(1, 2 - i * 0.3));
    line(0, 0, 0, -subLen);
    translate(0, -subLen);
    drawFernLeaf(subLen, max(1, iterations - 1), time, wind, i);
    pop();
  }
}

function drawFernLeaf(len, depth, time, wind, seed) {
  if (depth <= 0 || len < 3) return;

  let numPairs = 6;
  for (let i = 1; i <= numPairs; i++) {
    let t = i / numPairs;
    let subLen = len * 0.6 * (1 - t * 0.4);
    let yOffset = -len * (1 - t);

    push();
    translate(0, yOffset);

    // Right leaflet
    push();
    let rAngle = 42 + sin(time * 45 + i + seed) * wind * 2;
    rotate(rAngle);
    strokeWeight(max(0.5, depth * 0.5));
    line(0, 0, subLen, 0);
    if (depth > 1) {
      translate(subLen, 0);
      drawFernLeaf(subLen * 0.5, depth - 1, time, wind, seed + i);
    }
    pop();

    // Left leaflet
    push();
    let lAngle = -42 - cos(time * 40 + i + seed) * wind * 2;
    rotate(lAngle);
    strokeWeight(max(0.5, depth * 0.5));
    line(0, 0, -subLen, 0);
    if (depth > 1) {
      translate(-subLen, 0);
      drawFernLeaf(subLen * 0.5, depth - 1, time, wind, seed - i);
    }
    pop();

    pop();
  }
}

