{"title":"Seasonal Fractal Tree","code":"let angle = 0;

function setup() {
  createCanvas(windowWidth, windowHeight);
}

function draw() {
  let season = params.season;
  let bgCol;

  if (season === 'Spring') bgCol = color(240, 245, 250);
  else if (season === 'Summer') bgCol = color(220, 240, 250);
  else if (season === 'Autumn') bgCol = color(255, 243, 230);
  else bgCol = color(30, 35, 45);

  background(bgCol);

  let baseColor = color(params.trunkColor);
  stroke(baseColor);

  translate(width / 2, height);

  let len = height * 0.25;
  let maxDepth = floor(params.maxDepth);

  angle = sin(frameCount * 0.02 * params.speed) * 0.15;

  drawBranch(len, 0, maxDepth, season);
}

function drawBranch(len, depth, maxDepth, season) {
  if (depth > maxDepth) return;

  let sw = map(depth, 0, maxDepth, 14, 1);
  strokeWeight(max(sw, 1));

  if (params.season === 'Winter' && depth > 2) {
    stroke(200, 210, 230);
  } else {
    stroke(80, 50, 30);
  }

  line(0, 0, 0, -len);
  translate(0, -len);

  if (depth === maxDepth || (depth >= maxDepth - 2 && random() > 0.3)) {
    drawBlossom(season, len);
  }

  let branchAngle = radians(params.branchAngle) + angle * (depth / maxDepth);

  push();
  rotate(branchAngle);
  drawBranch(len * params.branchRatio, depth + 1, maxDepth, season);
  pop();

  push();
  rotate(-branchAngle);
  drawBranch(len * params.branchRatio, depth + 1, maxDepth, season);
  pop();
}

function drawBlossom(season, len) {
  push();
  noStroke();

  if (season === 'Spring') {
    fill(255, 182, 193, 200);
    ellipse(0, 0, len * 0.8, len * 0.8);
    fill(255, 255, 255, 220);
    ellipse(0, 0, len * 0.4, len * 0.4);
  } else if (season === 'Summer') {
    fill(50, 205, 50, 200);
    ellipse(0, 0, len * 0.9, len * 0.9);
    fill(34, 139, 34, 200);
    ellipse(len * 0.2, 0, len * 0.5, len * 0.5);
  } else if (season === 'Autumn') {
    let col = random() < 0.5 ? color(255, 140, 0, 220) : color(220, 20, 60, 220);
    fill(col);
    ellipse(0, 0, len * 0.8, len * 0.8);
  } else {
    fill(240, 248, 255, 220);
    ellipse(0, 0, len * 0.6, len * 0.6);
  }
  pop();
}

