  "title": "Sierpinski Dust",
  "code": "let particles = [];
let maxParticles = 3000;
let basePoints = [];

function setup() {
  createCanvas(windowWidth, windowHeight);
  colorMode(HSB, 360, 100, 100, 1);

  // Initialize particle pool
  for (let i = 0; i < maxParticles; i++) {
    particles.push(new DustParticle());
  }

  updateSierpinski();
}

function updateSierpinski() {
  basePoints = [];
  let size = min(width, height) * 0.75;
  let h = size * (sqrt(3) / 2);

  let x1 = width / 2;
  let y1 = height / 2 - h / 2;
  let x2 = width / 2 - size / 2;
  let y2 = height / 2 + h / 2;
  let x3 = width / 2 + size / 2;
  let y3 = height / 2 + h / 2;

  // Generate points using Chaos Game for Sierpinski triangle
  let currentX = x1;
  let currentY = y1;

  let targetCount = floor(map(params.detail, 1, 6, 200, maxParticles));
  targetCount = min(targetCount, maxParticles);

  let pts = [];
  // Warm up
  for (let i = 0; i < 20; i++) {
    let r = floor(random(3));
    if (r === 0) { currentX = (currentX + x1) / 2; currentY = (currentY + y1) / 2; }
    else if (r === 1) { currentX = (currentX + x2) / 2; currentY = (currentY + y2) / 2; }
    else { currentX = (currentX + x3) / 2; currentY = (currentY + y3) / 2; }
  }

  for (let i = 0; i < targetCount; i++) {
    let r = floor(random(3));
    if (r === 0) { currentX = (currentX + x1) / 2; currentY = (currentY + y1) / 2; }
    else if (r === 1) { currentX = (currentX + x2) / 2; currentY = (currentY + y2) / 2; }
    else { currentX = (currentX + x3) / 2; currentY = (currentY + y3) / 2; }
    pts.push(createVector(currentX, currentY));
  }

  // Assign to particles
  for (let i = 0; i < maxParticles; i++) {
    let p = particles[i];
    if (i < pts.length) {
      p.active = true;
      p.target.set(pts[i]);
    } else {
      p.active = false;
    }
  }
}

function draw() {
  background(10, 20, 10, 0.25);

  let time = millis() * 0.001 * params.speed;
  let dissolveAmt = (sin(time * 0.8) + 1) * 0.5; // Oscillates between 0 and 1

  // Recalculate targets periodically based on dissolve state to ensure fresh dust flow
  if (frameCount % 180 === 0) {
    updateSierpinski();
  }

  let activeCount = floor(map(params.detail, 1, 6, 200, maxParticles));

  for (let i = 0; i < maxParticles; i++) {
    let p = particles[i];
    if (i >= activeCount) {
      p.active = false;
      continue;
    } else {
      p.active = true;
    }
    p.update(dissolveAmt, time);
    p.display();
  }
}

class DustParticle {
  constructor() {
    this.pos = createVector(random(width), random(height));
    this.target = createVector(width / 2, height / 2);
    this.vel = createVector(0, 0);
    this.acc = createVector(0, 0);
    this.active = true;
    this.hueOffset = random(-30, 30);
    this.size = random(1.5, 3.5);
  }

  update(dissolve, t) {
    if (!this.active) return;

    // Noise force for dust behavior
    let noiseScale = 0.003;
    let nAngle = noise(this.pos.x * noiseScale, this.pos.y * noiseScale, t * 0.5) * TWO_PI * 2;
    let noiseForce = p5.Vector.fromAngle(nAngle).mult(params.turbulence * 1.5);

    // Pull towards target when triangle is formed (dissolve near 0)
    // Wander freely when dissolve is near 1
    let desired = p5.Vector.sub(this.target, this.pos);
    let d = desired.mag();

    let formWeight = map(dissolve, 0, 1, 1.0, 0.05);
    desired.normalize();
    let speedFactor = map(d, 0, width, 2, 20);
    desired.mult(speedFactor * formWeight);

    this.acc.set(0, 0);
    this.acc.add(desired);
    this.acc.add(noiseForce);

    // Add subtle mouse repulsion
    let mouse = createVector(mouseX, mouseY);
    let mouseDist = p5.Vector.dist(this.pos, mouse);
    if (mouseDist < 150) {
      let push = p5.Vector.sub(this.pos, mouse);
      push.normalize();
      push.mult((150 - mouseDist) * 0.1);
      this.acc.add(push);
    }

    this.vel.add(this.acc);
    this.vel.mult(0.85); // Damping
    this.pos.add(this.vel);
  }

  display() {
    if (!this.active) return;
    let baseHue = params.colorScheme === 'Neon Blue' ? 200 :
                  params.colorScheme === 'Solar Gold' ? 45 :
                  params.colorScheme === 'Cyber Pink' ? 320 : 160;

    let h = (baseHue + this.hueOffset + frameCount * 0.05) % 360;
    let alpha = map(this.vel.mag(), 0, 10, 0.4, 0.9);

    noStroke();
    fill(h, 80, 100, constrain(alpha, 0.2, 1.0));
    ellipse(this.pos.x, this.pos.y, this.size);

    // Luminous glow center
    fill(0, 0, 100, alpha * 0.5);
    ellipse(this.pos.x, this.pos.y, this.size * 0.5);
  }
}

