function setup() {
  createCanvas(windowWidth, windowHeight);
  angleMode(RADIANS);
}

function draw() {
  background(params.bgColor);

  let baseAngle = radians(params.spread);
  let len = height * 0.22 * params.size;

  push();
  translate(width / 2, height * 0.9);

  let branches = int(params.branches);
  let angleStep = branches > 1 ? baseAngle / (branches - 1) : 0;
  let startAngle = -baseAngle / 2;

  for (let i = 0; i < branches; i++) {
    let a = startAngle + i * angleStep;
    push();
    rotate(a);
    drawBranch(len, 1, params.depth);
    pop();
  }

  pop();
}

function drawBranch(len, depth, maxD) {
  if (depth > maxD) return;

  let timeOffset = frameCount * 0.02 * params.speed + depth * 0.5;
  let sway = sin(timeOffset) * 0.08 * (depth / maxD);

  let currentLen = len * (1.1 - depth * 0.08);

  stroke(params.coralColor);
  strokeWeight(max(1, (maxD - depth + 1) * 1.8 * params.thickness));
  noFill();

  beginShape();
  vertex(0, 0);
  bezierVertex(
    0, -currentLen * 0.3,
    sway * currentLen * 2, -currentLen * 0.7,
    sway * currentLen * 3, -currentLen
  );
  endShape();

  translate(sway * currentLen * 3, -currentLen);
  rotate(sway);

  let subBranches = 3;
  let subSpread = 0.8 + sin(frameCount * 0.01 * params.speed) * 0.1;

  for (let i = 0; i < subBranches; i++) {
    let subAngle = map(i, 0, subBranches - 1, -subSpread, subSpread);
    push();
    rotate(subAngle);
    drawBranch(len * 0.7, depth + 1, maxD);
    pop();
  }
}

