const maxDrops = 150;

function setup() {
  createCanvas(windowWidth, windowHeight);
  textAlign(CENTER, CENTER);
  textFont('sans-serif');

  for (let i = 0; i < maxDrops; i++) {
    drops.push(new Drop());
  }
}

function draw() {
  let bgCol = color(params.bgColor);
  background(red(bgCol), green(bgCol), blue(bgCol), 40);

  let activeCount = floor(map(params.density, 1, 10, 20, maxDrops));

  for (let i = 0; i < activeCount; i++) {
    drops[i].update();
    drops[i].display();
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

class Drop {
  constructor() {
    this.reset();
  }

  reset() {
    this.x = random(width);
    this.y = random(-height, 0);
    this.speed = random(2, 6);
    this.size = random(12, 36);
    this.word = params.wordText;
    this.phase = random(TWO_PI);
    this.charColor = color(params.textColor);
  }

  update() {
    this.y += this.speed * params.speed;

    if (this.y > height + 100) {
      this.reset();
      this.y = random(-200, -50);
    }
  }

  display() {
    push();
    translate(this.x, this.y);
    textSize(this.size);
    fill(this.charColor);
    noStroke();

    let letters = this.word.split('');
    let baseSpacing = this.size * 0.8 * params.spacing;

    for (let i = 0; i < letters.length; i++) {
      let ripple = sin(frameCount * 0.05 * params.rippleSpeed + this.phase + i * 0.5) * 8 * params.rippleAmount;
      let yOffset = i * baseSpacing + ripple;

      // Fade out letters towards the end of the word for depth
      let alpha = map(i, 0, letters.length, 255, 100);
      let c = color(this.charColor);
      c.setAlpha(alpha);
      fill(c);

      text(letters[i], 0, yOffset);
    }
    pop();
  }
