{"title":"Kinetic Orbit Typography","code":"let font;
let paths = [];

function setup() {
  createCanvas(windowWidth, windowHeight);
  angleMode(DEGREES);
  textAlign(CENTER, CENTER);
  rectMode(CENTER);
}

function draw() {
  background(params.bgColor);

  let numRings = int(params.rings);
  let word = params.text.toUpperCase();
  if (word.length === 0) word = "ORBIT";

  let baseRadius = min(width, height) * 0.1;
  let maxRadius = min(width, height) * 0.45;

  for (let i = 0; i < numRings; i++) {
    let t = numRings > 1 ? i / (numRings - 1) : 0.5;
    let r = lerp(baseRadius, maxRadius, t);

    let dir = (i % 2 === 0) ? 1 : -1;
    let speedFactor = params.speed * dir * (1 + i * 0.2);
    let angleOffset = frameCount * speedFactor + i * 45;

    let count = int(map(r, baseRadius, maxRadius, 6, 24));
    let stepAngle = 360 / count;

    for (let j = 0; j < count; j++) {
      let angle = j * stepAngle + angleOffset;
      let x = width / 2 + r * cos(angle);
      let y = height / 2 + r * sin(angle);

      let charIndex = (i + j) % word.length;
      let letter = word.charAt(charIndex);

      push();
      translate(x, y);

      if (params.rotateText) {
        rotate(angle + 90 * dir);
      } else {
        rotate(frameCount * params.speed * 0.5);
      }

      let sz = map(r, baseRadius, maxRadius, 12, 36) * params.textSize;
      textSize(sz);
      textStyle(BOLD);

      let col = lerpColor(color(params.color1), color(params.color2), i / max(1, numRings - 1));
      fill(col);
      noStroke();

      text(letter, 0, 0);
      pop();
    }

    if (params.showOrbits) {
      noFill();
      stroke(params.color1);
      strokeWeight(0.5);
      drawingContext.setLineDash([4, 8]);
      ellipse(width / 2, height / 2, r * 2);
      drawingContext.setLineDash([]);
    }
  }
}

