function draw() {
  background(params.bgColor);

  let t = millis() * 0.001 * params.speed;
  let stretch = params.stretch;

  // Generate word 'CANVAS' as points or use dynamic wavy strips
  let msg = "CANVAS";
  let baseSize = min(width, height) * 0.16;
  textSize(baseSize);
  textAlign(CENTER, CENTER);

  push();
  translate(width / 2, height / 2);

  // Draw elastic ribbons warping across the screen
  noFill();
  strokeWeight(params.ribbonWidth);

  for (let i = 0; i < numRibbons; i++) {
    let nVal = map(i, 0, numRibbons, 0, 1);

    // Color interpolation
    let c1 = color(params.color1);
    let c2 = color(params.color2);
    let c = lerpColor(c1, c2, nVal);
    stroke(red(c), green(c), blue(c), params.opacity);

    beginShape();
    let yOffset = map(i, 0, numRibbons, -height * 0.4, height * 0.4);

    for (let x = -width * 0.6; x <= width * 0.6; x += 20) {
      let noiseFactor = noise(x * 0.003, i * 0.2, t * 0.5);
      let wave = sin(x * 0.005 * stretch + t + i) * 60 * noiseFactor;
      let mouseDist = dist(x, yOffset, mouseX - width/2, mouseY - height/2);
      let mouseEffect = 0;
      if (mouseDist < 250) {
        mouseEffect = (1 - mouseDist / 250) * 80 * sin(t * 4);
      }

      let y = yOffset + wave + mouseEffect;
      vertex(x, y);
    }
    endShape();
  }

  // Elastic text stretched by breeze
  let textStretchX = 1 + sin(t * 0.8) * 0.2 * (stretch - 1);
  let textSkew = cos(t * 0.5) * 0.3;

  push();
  shearX(textSkew);
  scale(textStretchX, 1);

  // Glowing text shadow / multiple layers for elastic depth
  for (let layer = 5; layer > 0; layer--) {
    fill(0, 0, 0, 20);
    text(msg, layer * 2, layer * 2 + sin(t + layer) * 10);
  }

  fill(params.textColor);
  noStroke();
  text(msg, 0, sin(t * 1.5) * 20);

  pop();
  pop();
}

function windowResized() {
