  "title": "Interactive Constellation",
  "code": "let stars = [];

function setup() {
  createCanvas(windowWidth, windowHeight);
  let maxStars = 150;
  for (let i = 0; i < maxStars; i++) {
    stars.push(new Star());
  }
}

function draw() {
  background(params.bgColor);

  let currentCount = floor(params.starCount);
  let maxDist = params.connectionDistance;
  let speed = params.speed;
  let starColor = color(params.starColor);
  let lineColor = color(params.lineColor);

  for (let i = 0; i < currentCount; i++) {
    let s = stars[i];
    s.update(speed);
    s.display(starColor);

    for (let j = i + 1; j < currentCount; j++) {
      let other = stars[j];
      let d = dist(s.pos.x, s.pos.y, other.pos.x, other.pos.y);
      if (d < maxDist) {
        let alpha = map(d, 0, maxDist, 255, 0);
        stroke(red(lineColor), green(lineColor), blue(lineColor), alpha);
        strokeWeight(map(d, 0, maxDist, 1.5, 0.2));
        line(s.pos.x, s.pos.y, other.pos.x, other.pos.y);
      }
    }

    let md = dist(s.pos.x, s.pos.y, mouseX, mouseY);
    if (md < maxDist * 1.2 && (mouseX > 0 && mouseX < width && mouseY > 0 && mouseY < height)) {
      let alpha = map(md, 0, maxDist * 1.2, 255, 0);
      stroke(255, 200, 50, alpha);
      strokeWeight(1);
      line(s.pos.x, s.pos.y, mouseX, mouseY);

      // Slight pull towards mouse
      let force = p5.Vector.sub(createVector(mouseX, mouseY), s.pos);
      force.mult(0.0005 * params.mouseAttraction);
      s.vel.add(force);
    }
  }
}

class Star {
  constructor() {
    this.pos = createVector(random(width), random(height));
    this.vel = p5.Vector.random2D().mult(random(0.2, 1));
    this.size = random(1.5, 4);
  }

  update(speed) {
    let noiseVal = noise(this.pos.x * 0.005, this.pos.y * 0.005, frameCount * 0.005);
    let angle = noiseVal * TWO_PI * 2;
    let flowForce = p5.Vector.fromAngle(angle).mult(0.1);

    this.vel.add(flowForce);
    this.vel.limit(2);

    let sMove = p5.Vector.mult(this.vel, speed);
    this.pos.add(sMove);

    if (this.pos.x < 0) this.pos.x = width;
    if (this.pos.x > width) this.pos.x = 0;
    if (this.pos.y < 0) this.pos.y = height;
    if (this.pos.y > height) this.pos.y = 0;
  }

  display(col) {
    noStroke();
    fill(col);
    ellipse(this.pos.x, this.pos.y, this.size);
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
