{
  "title": "Elastic Spring Grid",
  "code": "let cols = 30;
let rows = 20;
let nodes = [];
let restLength;

function setup() {
  createCanvas(windowWidth, windowHeight);
  restLength = dist(0, 0, width / cols, height / rows);
  initGrid();
}

function initGrid() {
  nodes = [];
  let dx = width / cols;
  let dy = height / rows;
  for (let y = 0; y <= rows; y++) {
    for (let x = 0; x <= cols; x++) {
      let px = x * dx;
      let py = y * dy;
      nodes.push({
        x: px,
        y: py,
        ox: px,
        oy: py,
        vx: 0,
        vy: 0
      });
    }
  }
}

function draw() {
  background(params.bgColor);

  let stiffness = params.stiffness;
  let damping = params.damping;
  let mousePull = params.mousePull;
  let speed = params.speed;
  let showNodes = params.showNodes;

  // Update physics
  for (let y = 0; y <= rows; y++) {
    for (let x = 0; x <= cols; x++) {
      let i = x + y * (cols + 1);
      let n = nodes[i];

      // Spring back to origin
      let fx = (n.ox - n.x) * stiffness;
      let fy = (n.oy - n.y) * stiffness;

      // Mouse interaction
      let d = dist(mouseX, mouseY, n.x, n.y);
      if (d < 250 && d > 1) {
        let force = (1 - d / 250) * mousePull * 50;
        let angle = atan2(mouseY - n.y, mouseX - n.x);
        fx += cos(angle) * force;
        fy += sin(angle) * force;
      }

      n.vx = (n.vx + fx * speed) * damping;
      n.vy = (n.vy + fy * speed) * damping;
      n.x += n.vx * speed;
      n.y += n.vy * speed;
    }
  }

  // Draw grid lines
  stroke(params.lineColor);
  strokeWeight(1.5);
  noFill();

  // Horizontal lines
  for (let y = 0; y <= rows; y++) {
    beginShape();
    for (let x = 0; x <= cols; x++) {
      let n = nodes[x + y * (cols + 1)];
      curveVertex(n.x, n.y);
    }
    endShape();
  }

  // Vertical lines
  for (let x = 0; x <= cols; x++) {
    beginShape();
    for (let y = 0; y <= rows; y++) {
      let n = nodes[x + y * (cols + 1)];
      curveVertex(n.x, n.y);
    }
    endShape();
  }

  // Draw nodes
  if (showNodes) {
    fill(params.nodeColor);
    noStroke();
    for (let i = 0; i < nodes.length; i++) {
      let n = nodes[i];
      let speedMag = abs(n.vx) + abs(n.vy);
      let sz = constrain(2 + speedMag * 0.5, 2, 8);
      ellipse(n.x, n.y, sz, sz);
    }
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  restLength = dist(0, 0, width / cols, height / rows);
  initGrid();
