{
  "title": "Luminous Pond",
  "code": "let ripples = [];
let lastX = -1;
let lastY = -1;

function setup() {
  createCanvas(windowWidth, windowHeight);
  colorMode(HSB, 360, 100, 100, 1);
  noFill();
}

function draw() {
  background(params.bgColor);

  let s = params.speed;

  // Add ripple on mouse move
  if (mouseX !== lastX || mouseY !== lastY) {
    let d = dist(mouseX, mouseY, lastX, lastY);
    if (d > 15 / max(s, 0.1) && random() < 0.6) {
      ripples.push({
        x: mouseX,
        y: mouseY,
        r: 2,
        maxR: random(150, 350) * params.spread,
        alpha: 1,
        hue: (frameCount * 2 + random(360)) % 360
      });
      lastX = mouseX;
      lastY = mouseY;
    }
  }

  // Add ambient random ripples if enabled
  if (params.ambient && random() < 0.05 * s) {
    ripples.push({
      x: random(width),
      y: random(height),
      r: 2,
      maxR: random(100, 250) * params.spread,
      alpha: 0.8,
      hue: random(360)
    });
  }

  // Update and draw ripples
  for (let i = ripples.length - 1; i >= 0; i--) {
    let rip = ripples[i];

    rip.r += 2.5 * s;
    rip.alpha = map(rip.r, 0, rip.maxR, 1, 0);

    if (rip.alpha <= 0 || rip.r >= rip.maxR) {
      ripples.splice(i, 1);
      continue;
    }

    let col = color(rip.hue, 70, 90, rip.alpha * 0.7);
    stroke(col);
    strokeWeight(params.weight);
    ellipse(rip.x, rip.y, rip.r * 2);

    // Secondary inner ripple for glow effect
    if (params.glow) {
      let innerCol = color(rip.hue, 40, 100, rip.alpha * 0.4);
      stroke(innerCol);
      strokeWeight(params.weight * 0.5);
      ellipse(rip.x, rip.y, rip.r * 1.2);
    }
  }

  // Cap max ripples to prevent lag
  if (ripples.length > 150) {
    ripples.splice(0, ripples.length - 150);
  }
}

function mousePressed() {
  ripples.push({
    x: mouseX,
    y: mouseY,
    r: 2,
    maxR: 400 * params.spread,
    alpha: 1,
    hue: random(360)
  });
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
