{
  "title": "Neon Ring Swarm",
  "code": "let particles = [];
const maxParticles = 600;

function setup() {
  createCanvas(windowWidth, windowHeight);
  colorMode(HSB, 360, 100, 100, 1);
  for (let i = 0; i < maxParticles; i++) {
    particles.push(new Particle());
  }
}

function draw() {
  background(230, 80, 8, 0.25);

  let count = floor(map(params.density, 1, 5, 100, maxParticles));
  let targetRadius = min(width, height) * 0.3 * params.ringSize;

  for (let i = 0; i < count; i++) {
    let p = particles[i];
    p.update(targetRadius);
    p.display();
  }
}

class Particle {
  constructor() {
    this.pos = createVector(random(width), random(height));
    this.vel = createVector(0, 0);
    this.acc = createVector(0, 0);
    this.maxSpeed = random(4, 8);
    this.maxForce = 0.3;
    this.angle = random(TWO_PI);
    this.hue = random(160, 320);
  }

  update(targetRadius) {
    this.angle += 0.01 * params.speed;
    let ringX = width / 2 + cos(this.angle) * targetRadius;
    let ringY = height / 2 + sin(this.angle) * targetRadius;
    let target = createVector(ringX, ringY);

    let seekForce = this.arrive(target);
    seekForce.mult(0.8);
    this.acc.add(seekForce);

    let mouse = createVector(mouseX, mouseY);
    let d = p5.Vector.dist(this.pos, mouse);
    if (d < params.repelRadius) {
      let repel = p5.Vector.sub(this.pos, mouse);
      let strength = map(d, 0, params.repelRadius, 3, 0);
      repel.setMag(strength * 5 * params.speed);
      this.acc.add(repel);
    }

    let noiseVal = noise(this.pos.x * 0.005, this.pos.y * 0.005, frameCount * 0.01 * params.speed);
    let angleNoise = noiseVal * TWO_PI * 2;
    let noiseForce = p5.Vector.fromAngle(angleNoise);
    noiseForce.mult(0.5 * params.speed);
    this.acc.add(noiseForce);

    this.vel.add(this.acc);
    this.vel.limit(this.maxSpeed * params.speed);
    this.pos.add(this.vel);
    this.acc.mult(0);
  }

  arrive(target) {
    let desired = p5.Vector.sub(target, this.pos);
    let d = desired.mag();
    let speed = this.maxSpeed;
    if (d < 100) {
      speed = map(d, 0, 100, 0, this.maxSpeed);
    }
    desired.setMag(speed);
    let steer = p5.Vector.sub(desired, this.vel);
    steer.limit(this.maxForce);
    return steer;
  }

  display() {
    noStroke();
    fill(this.hue, 80, 100, 0.8);
    ellipse(this.pos.x, this.pos.y, 4, 4);
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}",
