  constructor() {
    this.reset();
  }

  reset() {
    this.x = random(width);
    this.y = random(height);
    this.r = random(15, 60);
    this.vx = random(-2, 2);
    this.vy = random(-2, 2);
    this.col = random(["#e63946", "#f1faee", "#a8dadc", "#457b9d", "#1d3557", "#ffb703"]);
  }

  update(spd) {
    this.x += this.vx * spd;
    this.y += this.vy * spd;

    if (this.x - this.r < 0 || this.x + this.r > width) {
      this.vx *= -1;
      this.x = constrain(this.x, this.r, width - this.r);
    }
    if (this.y - this.r < 0 || this.y + this.r > height) {
      this.vy *= -1;
      this.y = constrain(this.y, this.r, height - this.r);
    }
  }

  display() {
    fill(this.col);
    noStroke();
    ellipse(this.x, this.y, this.r * 2);

    fill(0, 0, 20);
    rect(this.x - this.r * 0.2, this.y - this.r * 0.2, this.r * 0.4, this.r * 0.4);
  }
}

