function setup() {
  createCanvas(windowWidth, windowHeight);
  rectMode(CENTER);
}
function draw() {
  background(255);
  let spd = params.speed;
  let gridSz = params.gridSize;
  let maxAmp = params.amplitude;
  let twistFac = params.twist;

  angle += 0.02 * spd;
  let cols = gridSz;
  let rows = gridSz;
  let w = width / cols;
  let h = height / rows;
  let maxDist = dist(0, 0, width / 2, height / 2);

  noStroke();
  for (let i = 0; i < cols; i++) {
    for (let j = 0; j < rows; j++) {
      let x = w * i + w / 2;
      let y = h * j + h / 2;
      let d = dist(x, y, width / 2, height / 2);

      let offset = sin(angle + d * 0.01 * twistFac) * maxAmp;
      let szFactor = map(sin(angle * 0.7 + d * 0.005), -1, 1, 0.4, 1.6);

      push();
      translate(x, y);
      rotate(d * 0.002 * twistFac + angle * 0.5);

      let cIndex = (i + j + floor(sin(angle + d * 0.02) * 3)) % 2;
      if (cIndex === 0) {
        fill(0);
      } else {
        fill(255);
        stroke(0);
        strokeWeight(1);
      }

      let boxW = w * szFactor + offset;
      let boxH = h * szFactor + offset;
      if (params.shape === "circle") {
        ellipse(0, 0, boxW, boxH);
      } else {
        rect(0, 0, boxW, boxH);
      }
      pop();
    }
  }
}
