let cols, rows;

function setup() {
  createCanvas(windowWidth, windowHeight);
  rectMode(CENTER);
  noFill();
  strokeWeight(params.lineWidth);
}

function draw() {
  background(params.bgColor);

  let s = params.tileSize;
  cols = floor(width / s) + 2;
  rows = floor(height / s) + 2;

  strokeWeight(params.lineWidth);

  let t = millis() * 0.001 * params.speed;

  let offsetX = (width % s) / 2;
  let offsetY = (height % s) / 2;

  for (let y = 0; y < rows; y++) {
    for (let x = 0; x < cols; x++) {
      push();
      let px = x * s + offsetX - s/2;
      let py = y * s + offsetY - s/2;
      translate(px + s/2, py + s/2);

      let n = noise(x * 0.1, y * 0.1, t * 0.2);
      let rot = floor(n * 4) * HALF_PI + t;
      rotate(rot);

      let col = getTileColor(x, y);
      stroke(col);

      if (params.patternType === "Arcs") {
        // Quarter circles
        arc(-s/2, -s/2, s, s, 0, HALF_PI);
        arc(s/2, s/2, s, s, PI, PI + HALF_PI);
      } else if (params.patternType === "Diagonals") {
        // Diagonal lines
        line(-s/2, -s/2, s/2, s/2);
        line(-s/2, s/2, s/2, -s/2);
      } else if (params.patternType === "Weave") {
        // Nested curves
        arc(-s/2, -s/2, s, s, 0, HALF_PI);
        arc(s/2, s/2, s, s, PI, PI + HALF_PI);
        arc(-s/2, -s/2, s*0.5, s*0.5, 0, HALF_PI);
        arc(s/2, s/2, s*0.5, s*0.5, PI, PI + HALF_PI);
      }
      pop();
    }
  }
}

function getTileColor(x, y) {
  let paletteType = params.colorPalette;
  if (paletteType === "Neon") {
    let val = (x + y + floor(millis() * 0.002 * params.speed)) % 3;
    if (val === 0) return color(0, 255, 200);
    if (val === 1) return color(255, 0, 128);
    return color(255, 220, 0);
  } else if (paletteType === "Sunset") {
    let mix = sin(x * 0.2 + millis() * 0.001 * params.speed) * 0.5 + 0.5;
    return lerpColor(color(255, 94, 77), color(90, 24, 154), mix);
  } else {
    let mix = (x * 0.1 + y * 0.1) % 1.0;
    return lerpColor(color(240, 240, 250), color(40, 40, 50), mix);
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
