{"title":"Swiss Oscillating Bars","code":"let gridCols = 12;
let gridRows = 8;

function setup() {
  createCanvas(windowWidth, windowHeight);
  rectMode(CORNER);
}

function draw() {
  background(250);

  let margin = 60;
  let availW = width - margin * 2;
  let availH = height - margin * 2;

  let colW = availW / gridCols;
  let rowH = availH / gridRows;

  let time = frameCount * 0.02 * params.speed;

  // Subtle background grid lines (Swiss structural precision)
  stroke(225);
  strokeWeight(1);
  for (let i = 0; i <= gridCols; i++) {
    let x = margin + i * colW;
    line(x, margin, x, height - margin);
  }
  for (let j = 0; j <= gridRows; j++) {
    let y = margin + j * rowH;
    line(margin, y, width - margin, y);
  }
  noStroke();

  let totalBars = params.barCount;

  for (let n = 0; n < totalBars; n++) {
    // Deterministic pseudo-random grid placement using sine/cosine offsets
    let colIdx = floor(abs(sin(n * 12.9898)) * gridCols);
    let rowIdx = floor(abs(cos(n * 78.233)) * gridRows);

    let x = margin + colIdx * colW;
    let y = margin + rowIdx * rowH;

    // Size derived from grid module
    let w = colW * (1 + floor(abs(sin(n * 45.5)) * 2));
    let h = rowH * 0.85;

    // Oscillation
    let oscFreq = 0.5 + (n % 3) * 0.5;
    let offset = n * 0.5;
    let progress = sin(time * oscFreq + offset);

    // Color alternating
    if (n % 2 === 0) {
      fill(params.primaryColor);
    } else {
      fill(20, 20, 20);
    }

    push();
    translate(x + colW / 2, y + rowH / 2);

    if (params.mode === "Scale & Shift") {
      let scaleW = map(progress, -1, 1, 0.2, 1.2);
      let shiftX = progress * colW * 0.5;
      rect(-w/2 + shiftX, -h/2, w * scaleW, h);
    } else if (params.mode === "Rotate & Expand") {
      let rot = progress * HALF_PI * 0.5;
      rotate(rot);
      let s = map(progress, -1, 1, 0.5, 1.1);
      rect(-w/2 * s, -h/2 * s, w * s, h * s);
    } else {
      // Pure translation
      let move = progress * colW;
      rect(-w/2 + move, -h/2, w, h);
    }

    pop();
  }

  // Typography element for Swiss style
  fill(20);
  noStroke();
  textSize(14);
  textFont("sans-serif");
  textStyle(BOLD);
  text("SWISS // GRID_OSC", margin, margin - 20);

  textStyle(NORMAL);
  textSize(10);
  text("SYS. 04", width - margin - 50, margin - 20);
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
