{"title":"Golden Chaos Double Pendulum","code":"let theta1 = 0;
let theta2 = 0;
let dTheta1 = 0;
let dTheta2 = 0;
let r1 = 150;
let r2 = 130;
let m1 = 20;
let m2 = 20;
let px2 = -1;
let py2 = -1;

function setup() {
  createCanvas(windowWidth, windowHeight);
  background(30, 30, 33);
  theta1 = PI / 2;
  theta2 = PI / 2;
}

function draw() {
  background(30, 30, 33, 25);

  let g = 1 * params.gravity;
  let steps = floor(params.speed * 5) + 1;

  push();
  translate(width / 2, height / 2 - 50);

  for (let s = 0; s < steps; s++) {
    let num1 = -g * (2 * m1 + m2) * sin(theta1) - m2 * g * sin(theta1 - 2 * theta2) - 2 * sin(theta1 - theta2) * m2 * (dTheta2 * dTheta2 * r2 + dTheta1 * dTheta1 * r1 * cos(theta1 - theta2));
    let den1 = r1 * (2 * m1 + m2 - m2 * cos(2 * theta1 - 2 * theta2));
    let alpha1 = num1 / den1;

    let num2 = 2 * sin(theta1 - theta2) * (dTheta1 * dTheta1 * r1 * (m1 + m2) + g * (m1 + m2) * cos(theta1) + dTheta2 * dTheta2 * r2 * m2 * cos(theta1 - theta2));
    let den2 = r2 * (2 * m1 + m2 - m2 * cos(2 * theta1 - 2 * theta2));
    let alpha2 = num2 / den2;

    dTheta1 += alpha1;
    dTheta2 += alpha2;
    theta1 += dTheta1;
    theta2 += dTheta2;

    dTheta1 *= 0.999;
    dTheta2 *= 0.999;
  }

  let x1 = r1 * sin(theta1);
  let y1 = r1 * cos(theta1);

  let x2 = x1 + r2 * sin(theta2);
  let y2 = y1 + r2 * cos(theta2);

  stroke(212, 175, 55, 30);
  strokeWeight(1);
  line(0, 0, x1, y1);
  line(x1, y1, x2, y2);

  fill(212, 175, 55, 100);
  noStroke();
  ellipse(x1, y1, m1);
  ellipse(x2, y2, m2);

  if (px2 !== -1) {
    stroke(255, 215, 0, params.glow * 255);
    strokeWeight(1.5);
    line(px2, py2, x2, y2);
  }

  px2 = x2;
  py2 = y2;

  pop();
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  background(30, 30, 33);
  px2 = -1;
  py2 = -1;
}","params":[{"id":"speed","name":"Simulation Speed","type":"number","default":1,"min":0.2,"max":3,"step":0.1},{"id":"gravity","name":"Gravity","type":"number","default":1,"min":0.1,"max":3,"step":0.1},{"id":"glow","name":"Trail Opacity","type":"number","default":0.6,"min":0.1,"max":1,"step":0.05}]}
